using Licitaciones.Application.TiposCambio;
using Licitaciones.Domain.TiposCambio;
namespace Licitaciones.UnitTests.Application.TiposCambio; public sealed class TipoCambioServiceTests { [Fact] public async Task ActivoUnicoYConversion() { var r = new Repo(); var s = new TipoCambioService(r); await s.CrearAsync(500m, true); await s.CrearAsync(510m, true); Assert.Equal(510m, (await s.ActivoAsync()).CrcPorUsd); Assert.Equal(2m, await s.ConvertirCrcAUsdAsync(1020m)); } private sealed class Repo : ITipoCambioRepository { readonly List<TipoCambio> x = []; public Task AgregarAsync(TipoCambio t, CancellationToken c = default) { x.Add(t); return Task.CompletedTask; } public Task<TipoCambio?> ObtenerAsync(Guid i, CancellationToken c = default) => Task.FromResult(x.SingleOrDefault(t => t.Id == i)); public Task<IReadOnlyList<TipoCambio>> ListarAsync(CancellationToken c = default) => Task.FromResult<IReadOnlyList<TipoCambio>>(x); public Task<TipoCambio?> ObtenerActivoAsync(CancellationToken c = default) => Task.FromResult(x.SingleOrDefault(t => t.Activo)); public Task GuardarAsync(CancellationToken c = default) => Task.CompletedTask; public Task EliminarAsync(TipoCambio t, CancellationToken c = default) { x.Remove(t); return Task.CompletedTask; } } }
